/** Keep a studio element where it was on screen across DOM swaps, so loading a video never throws the user down the page. */
function keepInView(element,action){const before=element.getBoundingClientRect().top;const finish=()=>{const delta=element.getBoundingClientRect().top-before;if(Math.abs(delta)>2)window.scrollBy({top:delta,behavior:'instant'});};const result=action();return result&&typeof result.then==='function'?result.finally(finish):(finish(),result);}
function formatDuration(seconds){if(!Number.isFinite(seconds))return '—';seconds=Math.max(0,Math.round(seconds));const h=Math.floor(seconds/3600),m=Math.floor(seconds%3600/60),s=seconds%60;return h?`${h} ${t('hours')} ${m} ${t('minutes')}`:m?`${m} ${t('minutes')} ${s} ${t('seconds')}`:`${s} ${t('seconds')}`;}
function formatClock(epochSeconds){if(!Number.isFinite(epochSeconds))return '';return new Date(epochSeconds*1000).toLocaleString(localeTag(),{hour12:false,timeZone:'Asia/Taipei',month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'});}
