async function loadFeature(item){
 if(robotType!==item.robot_type)await loadRobot(item.robot_type);
 sourceType='example';document.querySelectorAll('[data-source]').forEach(b=>b.classList.toggle('active',b.dataset.source==='example'));for(const t of ['example','youtube','upload'])$('source-'+t).hidden=t!=='example';
 await loadVideo({...item,type:'video_example',url:item.video_url,filename:L(item,'title'),title:L(item,'title')});
 person='reference-unassigned';$('pose-badge').textContent='ROBOT REFERENCE';$('source-watermark').textContent=tr('機器人原片參考 · 尚待姿態核對','Robot source reference · pose not yet verified');$('motion-note').textContent=tr('來源是 ','Source: ')+(L(item,'source_title')||tr('機器人展示','robot showcase'))+tr('，先分段建立動作；MediaPipe 人體模型不保證辨識機器人，需核對目標及關節。','. Build motions by segment first; the MediaPipe human model is not guaranteed to detect robots, so verify the target and joints.');
 $('play-reference').hidden=!item.motion_reference_url;studioViewer?.setMotion('stand');studioViewer?.setPlaying(false);renderFeatured();feedback(tr('已載入原影片 ','Loaded source video ')+item.start_s+'–'+item.end_s+tr(' 秒。可直接預覽、另切片段，或建立待 worker 的訓練工作。',' s. Preview it, cut another segment, or create a training job for the worker.'));
}
