 referencePlayer.clear();$('play-reference').hidden=true;clipEditor.clear();source={type:'example',id:'kungfu-demo'};sourceType='example';$('source-video').pause();$('source-video').hidden=true;$('youtube-embed').hidden=true;$('youtube-embed').src='';$('demo-backdrop').hidden=false;$('pose-overlay').hidden=false;$('source-label').textContent=tr('Kung Fu 示範','Kung Fu demo');$('pose-badge').textContent='DEMO POSE';$('source-watermark').textContent=tr('概念示範 · 非影片辨識結果','Concept demo · not video recognition');$('track-video').textContent=tr('播放示範中','Playing demo');feedback('');studioViewer?.setMotion('stand');studioViewer?.setPlaying(false);renderFeatured();await retarget.start({demo:true,robot:robot()});
