function renderLandmarks(){$('landmarks').replaceChildren();for(const item of catalog.capabilities.landmarks){const b=el('button',undefined,'landmark-card'+(item.id===landmark?' active':''));b.dataset.landmark=item.id;const art=el('span',undefined,'landmark-art');art.innerHTML='<svg viewBox="0 0 200 110" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linejoin="round">'+(drawings[item.id]||drawings.taipei101)+'</svg>';const caption=el('span',undefined,'landmark-caption');const [name,city]=L(item,'label').split(' · ');caption.append(el('strong',name),el('small',city+tr(' · 概念舞台',' · concept stage')));b.append(art,caption);b.setAttribute('aria-pressed',String(item.id===landmark));b.onclick=()=>{landmark=item.id;document.querySelectorAll('[data-landmark]').forEach(b=>{const active=b.dataset.landmark===landmark;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});studioViewer?.setLandmark(landmark);updateSummary();};$('landmarks').append(b);}}
