 referencePlayer.clear();$('play-reference').hidden=true;retarget.resetCapture();studioViewer?.setMotion('stand');person='reference-unassigned';$('youtube-embed').hidden=true;$('youtube-embed').src='';$('ingest-overlay').hidden=true;$('demo-backdrop').hidden=true;$('source-video').hidden=false;$('pose-overlay').hidden=false;$('source-video').poster=value.poster_url||'';$('source-video').src=value.url;$('source-video').loop=false;$('source-video').load();source={...value,type:value.type||'upload'};clipEditor.load(value);$('source-label').textContent=value.filename||tr('來源影片','Source video');$('pose-badge').textContent='MEDIAPIPE';$('source-watermark').textContent=tr('影片已載入 · 按開始辨識','Video loaded · press Start recognition');$('track-video').textContent=tr('開始辨識 ↗','Start recognition ↗');$('people').replaceChildren();$('people').dataset.signature='';$('motion-note').textContent=tr('播放影片後按「開始辨識」，載入 MediaPipe 模型並追蹤最多四位人物。','Play the video, then press “Start recognition” to load MediaPipe and track up to four people.');updateSummary();
