async function startTracking(){referencePlayer.clear();if(source.type==='example'){await demo();return;}if($('source-video').hidden){feedback(tr('需先取得可讀取影格的影片。請使用本機 yt-dlp 或上傳影片。','A video with readable frames is required. Use local yt-dlp or upload a video.'),true);return;}const button=$('track-video');button.disabled=true;try{clipEditor.stopPreview();studioViewer?.setPlaying(false);await retarget.start({demo:false,robot:robot(),segment:clipEditor.getSegment(),requireTargetSelection:source.type==='video_example'});$('source-watermark').textContent=source.type==='video_example'?tr('候選目標 · 請確認是否為來源機器人','Candidate target · confirm it is the source robot'):tr('MediaPipe Pose · 幾何關節映射','MediaPipe Pose · geometric joint mapping');button.textContent=tr('重新辨識 ↻','Re-run recognition ↻');feedback(source.type==='video_example'?tr('候選不會自動成為訓練目標。請核對來源機器人；若偵測的只有背景人物，保留為參考工作即可。','Candidates do not become training targets automatically. Verify the source robot; if only background people are detected, keep it as a reference job.'):tr('MediaPipe 已啟動，依顏色選擇人物。','MediaPipe started. Pick a person by color.'));}catch(e){feedback(e.message,true);}finally{button.disabled=false;}}
