/** Hero joint sliders: drive the loaded URDF joint by joint (geometry only, no physics). */
function jointLabel(name){return name.replace(/_joint$/,'').replace(/^center_/,'').replaceAll('_',' ');}
function renderJointPanel(){
 const states=heroViewer?.getJointStates?.()||[];const query=$('joint-filter').value.trim().toLowerCase();$('joint-sliders').replaceChildren();$('joint-panel-count').textContent=states.length?states.length+' DOF':'';
 if(!states.length){$('joint-sliders').append(el('p',t('joints_none'),'joint-empty'));return;}
 for(const joint of states){if(query&&!joint.name.toLowerCase().includes(query))continue;const row=el('label',undefined,'joint-row');const head=el('span',undefined,'joint-row-head');const value=el('output',joint.value.toFixed(2));head.append(el('span',jointLabel(joint.name)),value);const input=el('input');input.type='range';input.min=String(joint.lower);input.max=String(joint.upper);input.step='0.01';input.value=String(joint.value);input.setAttribute('aria-label',joint.name);input.oninput=()=>{const v=+input.value;value.textContent=v.toFixed(2);heroViewer?.setPlaying(false);heroViewer?.setJoints({[joint.name]:v});};row.append(head,input);$('joint-sliders').append(row);}
}
$('joint-filter').oninput=renderJointPanel;$('joint-reset').onclick=()=>{heroViewer?.setPlaying(false);heroViewer?.setMotion('stand',0);renderJointPanel();};
