/** Scene ribbon waits before expanding, so a quick pass of the pointer does not swap photos. */
{const slices=[...document.querySelectorAll('[data-sdk-slice]')];const dwellMs=340;const releaseMs=200;let dwell=0;const release=new WeakMap();
 const drop=(slice,keepOpen)=>{const was=slice.classList.contains('is-hot')||(!keepOpen&&slice.classList.contains('is-open'));slice.classList.remove('is-hot');if(!keepOpen)slice.classList.remove('is-open');if(slice.classList.contains('is-open')||!was)return;slice.classList.add('is-leaving');clearTimeout(release.get(slice));release.set(slice,setTimeout(()=>slice.classList.remove('is-leaving'),720));};
 slices.forEach(slice=>{
  slice.addEventListener('pointerenter',()=>{clearTimeout(dwell);clearTimeout(release.get(slice));dwell=setTimeout(()=>{slices.forEach(other=>{if(other!==slice)drop(other,other.classList.contains('is-open'));});slice.classList.add('is-hot');slice.classList.remove('is-leaving');},dwellMs);});
  slice.addEventListener('pointerleave',()=>{clearTimeout(dwell);clearTimeout(release.get(slice));release.set(slice,setTimeout(()=>{if(!slice.matches(':hover'))drop(slice,true);},releaseMs));});
  slice.addEventListener('click',()=>{clearTimeout(dwell);const on=slice.classList.contains('is-open');slices.forEach(other=>drop(other,false));if(!on){slice.classList.add('is-open','is-hot');slice.classList.remove('is-leaving');}});
 });}
